look.customCSS:
/* ───── 蓝夜蝴蝶 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") right 18px top 16%/26px 20px no-repeat,url("data:image/svg+xml;base64,") left 14px top 46%/20px 15px no-repeat,url("data:image/svg+xml;base64,") right 30px top 62%/16px 12px no-repeat,url("data:image/svg+xml;base64,") left bottom/200px 160px repeat-x,linear-gradient(180deg,#0B1450 0%,#13208A 40%,#1E2FB8 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：不做框，透明底往下淡出，底下一道发光的细白线 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,rgba(11,20,80,.85),rgba(11,20,80,0)) !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:8% !important;right:8% !important;bottom:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,255,255,.85),transparent) !important;box-shadow:0 0 8px rgba(200,215,255,.9) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.15em !important;text-shadow:0 0 8px rgba(200,215,255,.7) !important}
[data-wk="headdim"]{color:#C9D2FF !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#fff !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{flex:none !important;width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important;filter:drop-shadow(0 0 5px rgba(200,215,255,.7)) !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#fff !important}

/* 头像：泡在一团白光里，一圈白边，左上右下各停一只小蝴蝶 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important;box-shadow:0 0 0 3px #fff,0 0 16px 5px rgba(200,215,255,.75) !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-18% !important;top:-20% !important;width:52% !important;height:40% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(-14deg) !important;pointer-events:none !important;z-index:2 !important;filter:drop-shadow(0 0 4px rgba(200,215,255,.9)) !important;border:none !important;border-radius:0 !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;right:-14% !important;bottom:-10% !important;width:38% !important;height:29% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(-14deg) !important;pointer-events:none !important;z-index:2 !important;filter:drop-shadow(0 0 4px rgba(200,215,255,.9)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before,[data-wk="chathead"] button[data-wk="avatar"]::after,[data-wk="chathead"] span[data-wk="avatar"]::after{content:none !important}
[data-wk="chathead"] img[data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff,0 0 12px 3px rgba(200,215,255,.7) !important}

/* 他的话：过曝的一团白光——纯白底、深蓝字、外面一大圈光晕；一串第一条右上角停一只蝴蝶 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:10px !important;letter-spacing:.12em !important;padding:12px 22px !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#fff !important;color:#2235A8 !important;border:none !important;box-shadow:0 0 0 3px rgba(255,255,255,.55),0 0 22px 6px rgba(200,215,255,.7),0 0 46px 10px rgba(140,165,255,.35) !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-16px !important;top:-14px !important;width:30px !important;height:23px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(-14deg) !important;filter:drop-shadow(0 0 5px rgba(200,215,255,.95)) !important;animation:bbFlap 2.6s ease-in-out infinite !important}
@keyframes bbFlap{0%,100%{transform:rotate(-14deg) scaleX(1)}50%{transform:rotate(-14deg) scaleX(.72)}}
/* 我的话：深蓝玻璃，镶一圈白光，左上停一只蝴蝶 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,rgba(40,60,200,.9),rgba(26,42,158,.92)) !important;color:#fff !important;border:2px solid #fff !important;box-shadow:inset 0 0 12px rgba(200,215,255,.45),0 0 14px 2px rgba(200,215,255,.7) !important;text-shadow:0 0 6px rgba(200,215,255,.6) !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:-14px !important;top:-14px !important;width:30px !important;height:23px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(14deg) !important;filter:drop-shadow(0 0 5px rgba(200,215,255,.95)) !important;border:none !important}

/* 时间：一行带光的白字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#C9D2FF !important;letter-spacing:.3em !important;font-size:11.5px !important;text-shadow:0 0 6px rgba(200,215,255,.6) !important}
/* 已送达＝后面一个空心小圈；已读＝后面一只发光的小蝴蝶 */
[data-wk="meta"]{color:#C9D2FF !important;font-size:11px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:8px !important}
[data-wk="meta"]::after{content:"" !important;width:11px !important;height:11px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PGNpcmNsZSBjeD0nNicgY3k9JzYnIHI9JzMuNCcgZmlsbD0nbm9uZScgc3Ryb2tlPScjQzlEMkZGJyBzdHJva2Utd2lkdGg9JzEuMicvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{width:18px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px rgba(200,215,255,.95)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#fff !important;border:none !important;border-radius:10px !important;box-shadow:0 0 20px 5px rgba(200,215,255,.6) !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#2235A8 !important}
[data-wk="name"]{color:#C9D2FF !important}

/* 动描：没有框，淡蓝白斜体，带一点光，开头停一只小蝴蝶 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{position:relative !important;display:block !important;background:transparent !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#C9D2FF !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.1em !important;text-shadow:0 0 8px rgba(200,215,255,.55) !important;padding:2px 0 2px 26px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:0 !important;top:5px !important;width:18px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="myactink"]{padding:2px 26px 2px 0 !important;text-align:right !important}
[data-wk="myactink"]::before{left:auto !important;right:0 !important}
[data-wk="narrbar"]{background:rgba(11,20,80,.92) !important;border-top:1px solid rgba(255,255,255,.4) !important}
[data-wk="narrkind"]{border:1px solid rgba(255,255,255,.5) !important;border-radius:999px !important;background:transparent !important;color:#C9D2FF !important}
[data-wk="narrkind"][data-on="1"]{background:#fff !important;border-color:#fff !important;color:#2235A8 !important}
/* 系统提示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#C9D2FF !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnoteclose"]{color:#C9D2FF !important}

/* 底栏：不做框，透明底往上淡出，上沿一道发光细线；输入框是一块淡蓝玻璃；最右「让他回复」是一团白光 */
[data-wk="composer"]{position:relative !important;background:linear-gradient(180deg,rgba(30,47,184,0),rgba(19,32,138,.85)) !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:8% !important;right:8% !important;top:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,255,255,.85),transparent) !important;box-shadow:0 0 8px rgba(200,215,255,.9) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.1) !important;border:1px solid rgba(255,255,255,.55) !important;border-radius:12px !important;color:#fff !important;letter-spacing:.1em !important}
[data-wk="chatinput"]::placeholder{color:#C9D2FF !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 5px rgba(200,215,255,.7)) !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 0 5px rgba(200,215,255,.7)) !important}
[data-wk="chatreply"]{width:46px !important;min-width:46px !important;height:46px !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 12px rgba(200,215,255,.95)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:rgba(11,20,80,.95) !important;border-top:1px solid rgba(255,255,255,.4) !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
/* 头像上的蝴蝶（照参考）：他的停在头像右上和左下、往左歪；我的停在左上和右下、往右歪 */
[data-wk="msg"][data-me="0"] [data-wk="avatar"]::before,[data-wk="cardrow"]:not([data-me="1"]) [data-wk="avatar"]::before{left:auto !important;right:-18% !important;transform:rotate(-14deg) !important}
[data-wk="msg"][data-me="0"] [data-wk="avatar"]::after,[data-wk="cardrow"]:not([data-me="1"]) [data-wk="avatar"]::after{right:auto !important;left:-14% !important;transform:rotate(-14deg) !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"]::before,[data-wk="msg"][data-me="1"] [data-wk="avatar"]::after,[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]::before,[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]::after{transform:rotate(14deg) !important}
